BFS(G, s):
ewline 	ext{Initialize } Q 	ext{ as an empty queue}
ewline 	ext{Enqueue } s 	ext{ onto } Q
ewline 	ext{Mark } s 	ext{ as visited}
ewline 	ext{while } Q 	ext{ is not empty:}
ewline \quad u = 	ext{Dequeue from } Q
ewline \quad 	ext{for each unvisited neighbor } v 	ext{ of } u:
ewline \quad \quad 	ext{Mark } v 	ext{ as visited}
ewline \quad \quad 	ext{Enqueue } v 	ext{ onto } Q
